480		if rawUsageJSON == "" {
481			if reasoningContent != "" {
482				return len(reasoningContent) / 4, true
483			}
484			return 0, false
485		}
486		var raw struct {
487			CompletionTokensDetails struct {
488				// Pointer so absent vs. explicit-zero are distinguishable: nil means
489				// the field was not present; &0 means the server said "no reasoning".
490				ReasoningTokens *int `json:"reasoning_tokens"`
491			} `json:"completion_tokens_details"`
492			// Some non-OpenAI servers put reasoning_tokens at the top level.
493			ReasoningTokens *int `json:"reasoning_tokens,omitempty"`
494		}
495		if err := json.Unmarshal([]byte(rawUsageJSON), &raw); err != nil {
496			return 0, false
497		}
