208	func convertMessages(msgs []agent.Message) []ant.MessageParam {
209		var result []ant.MessageParam
210		for _, m := range msgs {
211			switch m.Role {
212			case agent.RoleUser:
213				result = append(result, ant.NewUserMessage(ant.NewTextBlock(m.Content)))
214			case agent.RoleAssistant:
215				if len(m.ToolCalls) > 0 {
216					var blocks []ant.ContentBlockParamUnion
217					if m.Content != "" {
218						blocks = append(blocks, ant.NewTextBlock(m.Content))
219					}
220					for _, tc := range m.ToolCalls {
221						var input interface{}
222						_ = json.Unmarshal(tc.Arguments, &input)
223						blocks = append(blocks, ant.NewToolUseBlock(tc.ID, input, tc.Name))
224					}
225					result = append(result, ant.NewAssistantMessage(blocks...))
226				} else {
227					result = append(result, ant.NewAssistantMessage(ant.NewTextBlock(m.Content)))
228				}
229			case agent.RoleTool:
230				result = append(result, ant.NewUserMessage(
231					ant.NewToolResultBlock(m.ToolCallID, m.Content, false),
232				))
233			}
234		}
235		return result
236	}
