// TestReasoningTokens_FallbackFromContent verifies the fallback behavior when usage omits reasoning-token counts.
// Per ADR-010 Amendment §8, reasoning tokens are extracted from message.reasoning_content when
// upstream usage blocks lack the count.
func TestReasoningTokens_FallbackFromContent(t *testing.T) {
	type tc struct {
		name             string
		rawUsageJSON     string
		reasoningContent string
		wantTokens       int
		wantApprox       bool
		desc             string
	}

	tests := []tc{
		{
			name: "usage_present_uses_usage",
			rawUsageJSON: mustMarshal(map[string]any{
				"prompt_tokens":     10,
				"completion_tokens": 50,
				"total_tokens":      60,
				"completion_tokens_details": map[string]any{
					"reasoning_tokens": 40,
				},
			}),
			reasoningContent: "some thinking text that is longer than the token count",
			wantTokens:       40,
			wantApprox:       false,
			desc:             "when both usage and content present, usage wins (not approximate)",
		},
		{
			name: "usage_absent_fallback_to_content",
			rawUsageJSON: mustMarshal(map[string]any{
				"prompt_tokens":     10,
				"completion_tokens": 50,
				"total_tokens":      60,
			}),
			reasoningContent: strings.Repeat("x", 120), // 120 chars → 30 tokens
			wantTokens:       30,
			wantApprox:       true,
